class Publisher { final int id; final String name; final String city; final int foundedYear; final DateTime? deletedAt; const Publisher({required this.id,required this.name,required this.city,required this.foundedYear,this.deletedAt}); bool get isDeleted=>deletedAt!=null; Publisher copyWith({int? id,String? name,String? city,int? foundedYear,DateTime? deletedAt,bool clearDeletedAt=false})=>Publisher(id:id??this.id,name:name??this.name,city:city??this.city,foundedYear:foundedYear??this.foundedYear,deletedAt:clearDeletedAt?null:(deletedAt??this.deletedAt)); Map<String,dynamic> toJson()=>{'id':id,'name':name,'city':city,'foundedYear':foundedYear,'deletedAt':deletedAt?.toIso8601String()}; factory Publisher.fromJson(Map<String,dynamic> j)=>Publisher(id:(j['id'] as num?)?.toInt()??0,name:j['name'] as String? ?? '',city:j['city'] as String? ?? '',foundedYear:(j['foundedYear'] as num?)?.toInt()??0,deletedAt:j['deletedAt']==null?null:DateTime.tryParse(j['deletedAt'].toString())); }
